// Erst die unterbrechende Warteschlange leeren, dann den Titel eintragen - siehe
// "Sofort spielen" in der Hauptdoku (Abschnitt 3). Eingabe am Ausloeser lesen.
const eingang = $('Eingang').first().json || {};
const pfad = String(eingang.pfad || $json.pfad || '').trim();
const titel = String(eingang.titel || $json.titel || '').trim() || pfad.split('/').pop();
if (!pfad) {
  return [{ json: { ergebnis: 'FEHLER: Kein pfad uebergeben. Rufe zuerst titel_suchen '
    + 'oder richtung_suchen auf und nimm den pfad aus dem Ergebnis.' } }];
}
let antwort = {};
try { antwort = $('Sofort eintragen').first().json || {}; } catch (e) { antwort = {}; }
const fehler = (antwort.errors || []).length || antwort.error;
return [{ json: { ergebnis: (fehler
  ? 'FEHLER beim Eintragen: ' + JSON.stringify(antwort.errors || antwort.error)
  : 'OK: "' + titel + '" laeuft jetzt sofort.'),
  pfad: pfad, titel: titel } }];
